SELECT NOTICES_ID, NOTICES_TITLE, NOTICES_IS_PINNED, NOTICES_CREATED_AT, NOTICES_CONTENT
FROM notices ORDER BY NOTICES_CREATED_AT DESC
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT NOTICES_ID, NOTICES_TITLE, NOTICES_IS_PINNED, NOTICES_CREATED_AT, NOTICES_CONTENT
FROM notices


        AND NOTICES_TITLE LIKE CONCAT('%', #{noticeSearchDTO.noticeTitle}, '%')


        AND NOTICES_CONTENT LIKE CONCAT('%', #{noticeSearchDTO.noticeContent}, '%')


        AND NOTICES_CREATED_AT >= #{noticeSearchDTO.noticeDateStart}


        AND NOTICES_CREATED_AT <= #{noticeSearchDTO.noticeDateEnd}


ORDER BY NOTICES_CREATED_AT DESC
LIMIT #{searchVO.rowStart}, #{searchVO.displayRowCount}

SELECT COUNT(*)
FROM notices


        AND NOTICES_TITLE LIKE CONCAT('%', #{noticeSearchDTO.noticeTitle}, '%')


        AND NOTICES_CONTENT LIKE CONCAT('%', #{noticeSearchDTO.noticeContent}, '%')


        AND NOTICES_CREATED_AT >= #{noticeSearchDTO.noticeDateStart}


        AND NOTICES_CREATED_AT <= #{noticeSearchDTO.noticeDateEnd}

